<?php
declare(strict_types=1);
namespace App\Interface\Http\Study\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Study\Service\ListStudyContestSubjectsService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class StudyContestController { public function __construct(private readonly AuthService $auth,private readonly ListStudyContestSubjectsService $subjects,private readonly ApiResponseFactory $responses){} public function subjects(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,string $positionId):ResponseInterface { try{$this->auth->currentUser($access);}catch(\DomainException|UnavailableUserException){return $this->responses->problem($response,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$request->getAttribute('request_id'));} if($positionId==='')return $this->responses->problem($response,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$request->getAttribute('request_id'));return $this->responses->success($response,$this->subjects->list($positionId),(string)$request->getAttribute('request_id')); } }
